const $ = (id) => document.getElementById(id);
const KEY = 'answersbook.web.records.v1';
let answers = [], records = [], current = null, phase = 'loading', tab = 'favorites';
let editingID = null, sharingRecord = null, shareBlob = null, shareURL = null, progress = 0, generation = 0, confirmAction = null;
let storageAvailable = true, sound = false, toastTimer;
const openVideo = $('open-video'), closeVideo = $('close-video'), poster = $('book-poster'), ink = $('reading-ink');
const sounds = { opening: new Audio('assets/audio/v0.3/open.wav'), closing: new Audio('assets/audio/v0.3/close.wav') };
Object.values(sounds).forEach(a => { a.preload = 'auto'; a.volume = .8; });
const escapeHTML = (value) => String(value).replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
function toast(message) { $('toast').textContent = message; $('toast').classList.add('visible'); clearTimeout(toastTimer); toastTimer = setTimeout(() => $('toast').classList.remove('visible'), 3500); }
try { const raw = localStorage.getItem(KEY); if (raw) { const parsed = JSON.parse(raw); if (!Array.isArray(parsed) || parsed.some(r => !r || typeof r.id !== 'string' || typeof r.zh !== 'string' || typeof r.en !== 'string' || !Number.isFinite(r.createdAt) || typeof r.favorite !== 'boolean' || typeof r.note !== 'string')) throw Error('invalid'); records = parsed; } sound = localStorage.getItem('answersbook.web.sound') === 'on'; }
catch { storageAvailable = false; setTimeout(() => toast('浏览器记录暂时不可用，本次仅临时保留；原存储不会被覆盖'), 500); }
function commit(next) { if (storageAvailable) { try { localStorage.setItem(KEY, JSON.stringify(next)); } catch { toast('记录未能保存，可能是浏览器存储空间不足'); return false; } } records = next; refreshCounts(); return true; }
function refreshCounts() { $('record-count').textContent = String(records.length).padStart(2, '0'); $('favorite-count').textContent = records.filter(r => r.favorite).length; $('history-count').textContent = records.length; updateCurrentFavorite(); }
function setPhase(value) { phase = value; const closed = value === 'closed', reading = value === 'reading'; $('book-trigger').disabled = !closed && !reading; $('trigger-text').textContent = closed ? '默念问题，翻开这本书' : reading ? '向右轻滑，或点击合书' : value === 'loading' ? '正在准备书页…' : '让书页慢慢落定…'; document.querySelector('.trigger-arrow').textContent = closed ? '←' : reading ? '→' : '·'; $('book-actions').hidden = !reading; $('book-stage').setAttribute('aria-label', closed ? '答案之书。点击或向左滑动开书' : reading && current ? `${current.zh}，${current.en}。第${current.page}页，点击底部合书` : '翻书动画进行中'); }
function stopAudio() { Object.values(sounds).forEach(a => { a.pause(); a.currentTime = 0; }); }
function updateSoundButton() { $('sound-toggle').textContent = sound ? '声音开启' : '声音关闭'; $('sound-toggle').setAttribute('aria-pressed', String(sound)); }
$('sound-toggle').addEventListener('click', () => { sound = !sound; if (!sound) stopAudio(); try { localStorage.setItem('answersbook.web.sound', sound ? 'on' : 'off'); } catch {} updateSoundButton(); });
function updateCurrentFavorite() { const record = current && records.find(r => r.id === current.id); $('favorite-current').textContent = record?.favorite ? '★ 已收藏' : '☆ 收藏'; }
const mask = document.createElement('canvas'); mask.width = 115; mask.height = 250; const maskContext = mask.getContext('2d');
const noise = new Float32Array(mask.width * mask.height); let seed = 45;
for (let i = 0; i < noise.length; i++) { const x = i % mask.width, y = Math.floor(i / mask.width); seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0; noise[i] = .48 + Math.sin(x * .45 + Math.cos(y * .08)) * .16 + Math.cos(y * .29 + x * .06) * .14 + (seed / 4294967296 - .5) * .3; }
function paintInk(value) { progress = value; if (value >= 1) { ink.style.maskImage = ink.style.webkitMaskImage = 'none'; return; } if (value <= 0) { ink.style.maskImage = ink.style.webkitMaskImage = 'linear-gradient(transparent,transparent)'; return; } const pixels = maskContext.createImageData(mask.width, mask.height); for (let i = 0; i < noise.length; i++) { const offset = i * 4; pixels.data[offset] = pixels.data[offset+1] = pixels.data[offset+2] = 255; pixels.data[offset+3] = Math.round(Math.max(0, Math.min(1, (value - noise[i]) * 12 + .5)) * 255); } maskContext.putImageData(pixels, 0, 0); const url = `url(${mask.toDataURL()})`; ink.style.maskImage = ink.style.webkitMaskImage = url; ink.style.maskSize = ink.style.webkitMaskSize = '100% 100%'; }
function animateInk(from, to, duration, token, done) { const start = performance.now(); function frame(now) { if (token !== generation || document.hidden) return; const t = Math.min(1, (now - start) / duration); paintInk(from + (to - from) * t); if (t < 1) requestAnimationFrame(frame); else done?.(); } requestAnimationFrame(frame); }
function showStatic(reading) { [openVideo, closeVideo].forEach(v => { v.pause(); v.classList.remove('active-video'); }); poster.src = reading ? 'assets/book/v0.4/reading.png' : 'assets/book/v0.4/closed.png'; }
function showAnswer(record) { $('answer-zh').textContent = record.zh; $('answer-en').textContent = record.en; $('answer-page').textContent = record.page; ink.hidden = false; }
async function playBook(open, token) { const video = open ? openVideo : closeVideo; video.currentTime = 0; let firstFrame = false; const makeVisible = () => { if (token === generation && !firstFrame) { firstFrame = true; video.classList.add('active-video'); } }; if ('requestVideoFrameCallback' in video) video.requestVideoFrameCallback(makeVisible); else video.addEventListener('playing', makeVisible, {once:true}); const effect = sounds[open ? 'opening' : 'closing']; stopAudio(); if (sound) { effect.currentTime = 0; effect.play().catch(() => {}); }
 video.onended = () => { if (token !== generation) return; stopAudio(); showStatic(open); if (open) { showAnswer(current); paintInk(0); setPhase('revealing'); animateInk(0, 1, 1500, token, () => setPhase('reading')); } else { ink.hidden = true; current = null; setPhase('closed'); } };
 video.ontimeupdate = () => { if (sound && !effect.paused && Math.abs(effect.currentTime - video.currentTime) > .12) effect.currentTime = Math.min(video.currentTime, Math.max(0, (effect.duration || 2) - .01)); };
 try { await video.play(); } catch { if (token !== generation) return; stopAudio(); showStatic(open); if (open) { showAnswer(current); paintInk(1); setPhase('reading'); } else { ink.hidden = true; current = null; setPhase('closed'); } toast('动画暂未播放，已显示静态书页，可以继续体验'); }
}
function openBook() { if (phase !== 'closed' || !answers.length) return; const random = new Uint32Array(1); crypto.getRandomValues(random); const page = random[0] % answers.length + 1; const answer = answers[page - 1]; const record = {id:crypto.randomUUID ? crypto.randomUUID() : `record-${Date.now()}-${random[0]}`, answerID:answer.id, zh:answer.zh, en:answer.en, page, createdAt:Date.now(), favorite:false, note:''}; if (!commit([record, ...records])) return; current = record; const token = ++generation; ink.hidden = true; setPhase('opening'); playBook(true, token); }
function closeBook() { if (phase !== 'reading' && phase !== 'revealing') return; const from = progress; const token = ++generation; setPhase('erasing'); animateInk(from, 0, 750, token, () => { ink.hidden = true; setPhase('closing'); playBook(false, token); }); }
$('book-trigger').addEventListener('click', e => { e.stopPropagation(); if (phase === 'closed') openBook(); else closeBook(); });
$('book-stage').addEventListener('click', e => { if (e.target.closest('button')) return; if (phase === 'closed') openBook(); });
$('book-stage').addEventListener('keydown', e => { if (e.target !== $('book-stage')) return; if (['ArrowLeft','Enter',' '].includes(e.key) && phase === 'closed') { e.preventDefault(); openBook(); } else if (['ArrowRight','Escape'].includes(e.key)) { e.preventDefault(); closeBook(); } });
let pointer = null; $('book-stage').addEventListener('pointerdown', e => { if (!e.target.closest('button')) pointer = {x:e.clientX,y:e.clientY}; }); $('book-stage').addEventListener('pointerup', e => { if (!pointer) return; const dx = e.clientX - pointer.x, dy = e.clientY - pointer.y; pointer = null; if (Math.abs(dx) < 45 || Math.abs(dx) < Math.abs(dy) * 1.2) return; if (dx < 0) openBook(); else closeBook(); }); $('book-stage').addEventListener('pointercancel', () => {pointer = null;});
document.addEventListener('visibilitychange', () => { if (!document.hidden) return; const previous = phase; generation++; stopAudio(); if (['opening','revealing','reading'].includes(previous) && current) { showStatic(true); showAnswer(current); paintInk(1); setPhase('reading'); } else if (['closing','erasing'].includes(previous)) { showStatic(false); ink.hidden = true; current = null; setPhase('closed'); } });
function favorite(id) { const next = records.map(r => r.id === id ? {...r, favorite:!r.favorite} : r); if (commit(next)) { renderLibrary(); updateCurrentFavorite(); } }
$('favorite-current').addEventListener('click', () => current && favorite(current.id));
function openNote(id) { const record = records.find(r => r.id === id); if (!record) return toast('这条记录已经删除'); editingID = id; $('note-answer').textContent = `${record.zh}\n${record.en}`; $('note-input').value = record.note; $('note-dialog').showModal(); }
$('note-current').addEventListener('click', () => current && openNote(current.id)); $('note-clear').addEventListener('click', () => {$('note-input').value='';$('note-input').focus();});
$('note-save').addEventListener('click', () => { const text = $('note-input').value; if (!records.some(r => r.id === editingID)) return toast('记录已不存在，备注没有保存'); if (commit(records.map(r => r.id === editingID ? {...r,note:text} : r))) { $('note-dialog').close(); renderLibrary(); toast('已保存此刻的问题'); } });
function askConfirm(title, message, callback) { $('confirm-title').textContent = title; $('confirm-message').textContent = message; confirmAction = callback; $('confirm-dialog').showModal(); }
$('confirm-cancel').addEventListener('click', () => {$('confirm-dialog').close();confirmAction=null;}); $('confirm-accept').addEventListener('click', () => { const action = confirmAction; confirmAction = null; $('confirm-dialog').close(); action?.(); });
$('clear-history').addEventListener('click', () => askConfirm('清空未收藏历史？','只删除未收藏的记录，收藏及其问题备注会保留。', () => { if (commit(records.filter(r => r.favorite))) renderLibrary(); }));
function renderLibrary() { $('tab-favorites').setAttribute('aria-selected', String(tab === 'favorites')); $('tab-history').setAttribute('aria-selected', String(tab === 'history')); $('library-subtitle').textContent = tab === 'favorites' ? '留住一句触动你的话' : '每一次翻阅，都是一个新的角度'; $('clear-history').hidden = tab !== 'history' || !records.some(r => !r.favorite); const list = tab === 'favorites' ? records.filter(r => r.favorite) : records; if (!list.length) { $('library-list').innerHTML = `<div class="empty-state"><span>${tab === 'favorites' ? '✧' : '◷'}</span><h3>${tab === 'favorites' ? '还没有收藏' : '还没有翻阅记录'}</h3><p>${tab === 'favorites' ? '遇见喜欢的一页，轻点收藏，留给以后的自己' : '带着一个小问题，翻开这本书'}</p></div>`; return; }
 $('library-list').innerHTML = list.map(r => `<article class="record-card" data-id="${escapeHTML(r.id)}"><div class="record-meta"><time>${escapeHTML(new Date(r.createdAt).toLocaleString('zh-CN',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}))}</time><span>${r.favorite ? '★ 已收藏' : `第 ${escapeHTML(r.page)} 页`}</span></div><div class="record-answer"><h3>${escapeHTML(r.zh)}</h3><p lang="en">${escapeHTML(r.en)}</p></div>${r.note ? `<div class="record-note"><small>我的问题</small>${escapeHTML(r.note)}</div>` : ''}<div class="record-actions"><button data-action="note">${r.note ? '编辑问题' : '添加问题或备注'}</button><button data-action="share">↗ 分享</button><button data-action="favorite">${r.favorite ? '取消收藏' : '☆ 收藏'}</button>${tab === 'history' ? '<button class="remove" data-action="delete">删除记录</button>' : ''}</div></article>`).join(''); }
$('library-list').addEventListener('click', e => { const button = e.target.closest('button[data-action]'); if (!button) return; const id = button.closest('[data-id]').dataset.id, record = records.find(r => r.id === id); if (!record) return; const action = button.dataset.action; if (action === 'favorite') favorite(id); if (action === 'note') openNote(id); if (action === 'share') openShare(record); if (action === 'delete') askConfirm('删除这条记录？', record.favorite ? '这条记录已收藏。删除后，收藏和问题备注也会一起删除，无法恢复。' : '这次翻阅及其问题备注将删除，无法恢复。', () => {if(commit(records.filter(r=>r.id!==id)))renderLibrary();}); });
$('library-open').addEventListener('click', () => {tab='favorites';renderLibrary();$('library-dialog').showModal();}); $('tab-favorites').addEventListener('click',()=>{tab='favorites';renderLibrary();}); $('tab-history').addEventListener('click',()=>{tab='history';renderLibrary();});
for(const id of ['about','credits']) $(id+'-open').addEventListener('click',()=>$(id+'-dialog').showModal()); document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>$(b.dataset.close).close())); document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const box=d.getBoundingClientRect();if(e.clientX<box.left||e.clientX>box.right||e.clientY<box.top||e.clientY>box.bottom)d.close();}}));
function wrappedLines(ctx, text, width) { const result = []; for (const paragraph of text.split('\n')) { if (!paragraph) {result.push('');continue;} let line = ''; const tokens = paragraph.match(/[A-Za-z0-9]+(?:['’-][A-Za-z0-9]+)*\s*|\s+|[^A-Za-z0-9\s]/gu) || []; for (const token of tokens) { if (ctx.measureText(line+token).width > width && line) { result.push(line.trimEnd()); line=''; } if (ctx.measureText(token).width > width) { for (const ch of token) {if(ctx.measureText(line+ch).width>width&&line){result.push(line);line='';}line+=ch;} } else line+=token; } if(line)result.push(line.trimEnd()); }return result; }
async function generateShare() { const record = sharingRecord; if (!record) return; await document.fonts.ready; const include = $('share-include-note').checked && record.note; const probe=document.createElement('canvas').getContext('2d'); probe.font='28px BookSerif'; const zh=wrappedLines(probe,record.zh,300);probe.font='18px Georgia';const en=wrappedLines(probe,record.en,300);probe.font='16px BookSerif';const note=include?wrappedLines(probe,record.note,300):[];const contentHeight=zh.length*42+en.length*25+(note.length?56+note.length*24:0);const height=Math.max(490,48+22+48+contentHeight+48+1+18+23+36); if(height>20000){$('share-error').textContent='备注较长，暂时无法生成完整图片。可关闭“包含我的问题”后分享答案。';shareBlob=null;$('share-download').disabled=true;return;}
 const scale=Math.min(3,Math.sqrt(12000000/(360*height))); const canvas=document.createElement('canvas');canvas.width=Math.round(360*scale);canvas.height=Math.round(height*scale);const ctx=canvas.getContext('2d');ctx.scale(scale,scale);const gradient=ctx.createLinearGradient(0,0,360,height);gradient.addColorStop(0,'#faf5e9');gradient.addColorStop(1,'#efe4cc');ctx.fillStyle=gradient;ctx.fillRect(0,0,360,height);let n=45;ctx.strokeStyle='#9d7e4c18';ctx.lineWidth=.3;for(let i=0;i<2400;i++){n=(Math.imul(n,1664525)+1013904223)>>>0;const x=(n%10000)/10000*360;n=(Math.imul(n,1664525)+1013904223)>>>0;const y=(n%10000)/10000*height;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+1+n%4,y+.5);ctx.stroke();}ctx.strokeStyle='#a98c5b55';ctx.lineWidth=.6;ctx.strokeRect(.5,.5,359,height-1);ctx.strokeRect(15,15,330,height-30);ctx.strokeStyle='#9b7e4e88';ctx.beginPath();ctx.moveTo(130,61);ctx.lineTo(230,61);ctx.stroke();ctx.beginPath();ctx.ellipse(180,61,7,5,-.4,0,Math.PI*2);ctx.stroke();ctx.textAlign='center';ctx.fillStyle='#392b1e';ctx.font='28px BookSerif';let y=note.length?136:Math.max(136,(height-140-contentHeight)/2);for(const line of zh){ctx.fillText(line,180,y);y+=42;}ctx.font='18px Georgia';ctx.fillStyle='#7c6851';for(const line of en){ctx.fillText(line,180,y-6);y+=25;}if(note.length){y+=30;ctx.textAlign='left';ctx.font='12px BookSerif';ctx.fillStyle='#a18555';ctx.fillText('我的问题',30,y);y+=27;ctx.font='16px BookSerif';ctx.fillStyle='#51422f';for(const line of note){ctx.fillText(line,30,y);y+=24;}}ctx.strokeStyle='#a184534d';ctx.beginPath();ctx.moveTo(148,height-77);ctx.lineTo(212,height-77);ctx.stroke();ctx.font='15px BookSerif';ctx.fillStyle='#a08656';ctx.textAlign='center';ctx.fillText('答 案 之 书',180,height-37);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)return; if(record!==sharingRecord)return; if(shareURL)URL.revokeObjectURL(shareURL);shareBlob=blob;shareURL=URL.createObjectURL(blob);$('share-image').src=shareURL;$('share-image').alt=`${record.zh}，${record.en}${include?'，'+record.note:''}，答案之书`;$('share-error').textContent='';$('share-download').disabled=false;$('share-native').hidden=typeof navigator.canShare!=='function'||!navigator.canShare({files:[new File([blob],'答案之书.png',{type:'image/png'})]}); }
function openShare(record) { sharingRecord={...record};$('share-include-note').checked=false;$('share-include-note').parentElement.hidden=!record.note;$('share-error').textContent='';$('share-dialog').showModal();generateShare(); }
$('share-current').addEventListener('click',()=>{const r=current&&records.find(r=>r.id===current.id);if(r)openShare(r);else if(current)openShare(current);});$('share-include-note').addEventListener('change',generateShare);$('share-download').addEventListener('click',()=>{if(!shareBlob)return;const a=document.createElement('a');a.href=shareURL;a.download=`答案之书_第${sharingRecord.page}页.png`;a.click();toast('已生成图片，可在浏览器下载中查看');});$('share-native').addEventListener('click',async()=>{if(!shareBlob)return;try{await navigator.share({files:[new File([shareBlob],'答案之书.png',{type:'image/png'})],title:'答案之书'});}catch(e){if(e.name!=='AbortError')toast('当前浏览器无法系统分享，请保存图片后使用');}});
async function init() { updateSoundButton();refreshCounts();setPhase('loading');try{const response=await fetch('assets/answers/v0.2/answers.json');if(!response.ok)throw Error('load');answers=await response.json();if(answers.length!==120||answers.some((a,i)=>a.id!==`answer_${String(i+1).padStart(3,'0')}`||!a.zh||!a.en))throw Error('format');setPhase('closed');}catch{setPhase('loading');$('trigger-text').textContent='答案库加载失败，请刷新后重试';toast('请通过网页服务器或发布链接打开，不能直接双击HTML文件');}}
init();
